CREATE TABLE IF NOT EXISTS organisations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS garages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organisation_id uuid NOT NULL REFERENCES organisations(id), name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE CHECK(email=lower(email)), name text NOT NULL, role text NOT NULL CHECK(role IN ('platform_admin','organisation_admin','garage_manager','mechanic')), organisation_id uuid REFERENCES organisations(id), garage_id uuid REFERENCES garages(id), password_hash text, credential_version integer NOT NULL DEFAULT 1, active boolean NOT NULL DEFAULT true, bootstrap boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), last_login timestamptz, CHECK ((role='platform_admin' AND organisation_id IS NULL AND garage_id IS NULL) OR (role='organisation_admin' AND organisation_id IS NOT NULL AND garage_id IS NULL) OR (role IN ('garage_manager','mechanic') AND organisation_id IS NOT NULL AND garage_id IS NOT NULL)));
CREATE TABLE IF NOT EXISTS sessions(token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), credential_version integer NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS sessions_user_idx ON sessions(user_id);
CREATE TABLE IF NOT EXISTS activation_tokens(token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), credential_version integer NOT NULL, expires_at timestamptz NOT NULL, used_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS activation_user_idx ON activation_tokens(user_id);
CREATE TABLE IF NOT EXISTS auth_limits(key text PRIMARY KEY, attempts integer NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS garage_records(garage_id uuid PRIMARY KEY REFERENCES garages(id), version integer NOT NULL DEFAULT 0, data jsonb NOT NULL DEFAULT '{"schema":1,"vehicles":[],"reports":[],"faults":[],"actions":[],"inspections":[]}'::jsonb, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_events(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, actor_id uuid REFERENCES users(id), action text NOT NULL, target text, garage_id uuid REFERENCES garages(id), created_at timestamptz NOT NULL DEFAULT now());
